#include "../../sdk/application.h"
#include "../../sdk/stream.h"
static struct cb_client client;
__attribute__((noreturn)) void _start(const struct cb_startup *packet){struct cb_application_start start;CB_REQUIRE(cb_application_start(packet,&start) && start.header.cwd_bytes<4096 && start.header.argc<=3);char cwd[4096],path[4096];cb_copy(cwd,start.cwd,start.header.cwd_bytes);cwd[start.header.cwd_bytes]=0;int all=0;const char *argument=".";int selected=0;for(uint64_t i=1;i<start.header.argc;++i){const char *a=cb_application_argument(&start,i);if(a[0]=='-' && a[1]=='a' && !a[2])all=1;else {CB_REQUIRE(!selected);argument=a;selected=1;}}CB_REQUIRE(cb_path(path,sizeof(path),cwd,argument));cb_handle_t fs=cb_acquire(CB_FILESYSTEM_NAME,(struct cb_interface_id)CB_FILESYSTEM_INTERFACE_ID),out=cb_standard(1);if(!out)cb_exit(CB_BAD_HANDLE);uint64_t cursor=0;unsigned column=0;for(;;){cb_status_t status=cb_fs_call(&client,fs,CB_FILESYSTEM_LIST,path,0,cursor);if(status){cb_handle_t error=cb_standard(2);static const char message[]="ls: cannot list directory\n";if(error)(void)cb_write_all(&client,error,message,sizeof(message)-1);cb_exit(status);}struct cb_reply_header h;cb_copy(&h,client.result,sizeof(h));if(!h.result_bytes)break;struct cb_filesystem_entry e;cb_copy(&e,cb_result(&client),sizeof(e));if(e.cursor<=cursor || e.name_bytes>255)cb_exit(CB_BAD_REQUEST);cursor=e.cursor;if(!all && e.name_bytes && e.name[0]=='_')continue;if((e.name_bytes==1 && e.name[0]=='.') || (e.name_bytes==2 && e.name[0]=='.' && e.name[1]=='.'))continue;CB_REQUIRE(cb_write_all(&client,out,e.name,e.name_bytes)==CB_OK);unsigned used=e.name_bytes;if(e.directory){CB_REQUIRE(cb_write_all(&client,out,"/",1)==CB_OK);++used;}if(++column==4){CB_REQUIRE(cb_write_all(&client,out,"\n",1)==CB_OK);column=0;}else {static const char spaces[]="                    ";CB_REQUIRE(cb_write_all(&client,out,spaces,used<20?20-used:1)==CB_OK);}}if(column)CB_REQUIRE(cb_write_all(&client,out,"\n",1)==CB_OK);cb_exit(0);}
